import{_ as t,o as e,c as s,a2 as i}from"./chunks/framework.DpEPdvMq.js";const m=JSON.parse('{"title":"根据会话历史生成 Git 提交信息","description":"","frontmatter":{"tags":["git","automation","ai"],"version":"1.0.0","last_updated":"2026-09-04T00:00:00.000Z"},"headers":[],"relativePath":"05-git/commit-from-session.md","filePath":"05-git/commit-from-session.md"}'),o={name:"05-git/commit-from-session.md"};function l(r,a,n,p,c,d){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="根据会话历史生成-git-提交信息" tabindex="-1">根据会话历史生成 Git 提交信息 <a class="header-anchor" href="#根据会话历史生成-git-提交信息" aria-label="Permalink to &quot;根据会话历史生成 Git 提交信息&quot;">​</a></h1><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>你通过 AI 辅助完成代码改动后，希望 AI 根据本次会话中的所有修改自动生成提交信息，无需手动描述改动内容。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>本次会话中 AI 已帮你生成或修改了代码</li><li>改动尚未提交到 Git</li></ul><h2 id="提示词模板" tabindex="-1">提示词模板 <a class="header-anchor" href="#提示词模板" aria-label="Permalink to &quot;提示词模板&quot;">​</a></h2><p>请回顾本次会话中我们完成的所有代码改动，生成一条符合 Conventional Commits 规范的 Git 提交信息。</p><p><strong>提取规则：</strong></p><ol><li>总结本次会话涉及的核心功能或修复</li><li>列出关键改动点（文件级别或功能级别）</li><li>根据改动性质自动推断 type（feat/fix/refactor/perf/docs/style/test/chore）</li><li>根据改动的模块自动推断 scope</li></ol><p><strong>输出格式：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;(&lt;scope&gt;): &lt;中文主题&gt;</span></span>
<span class="line"><span>- &lt;中文改动点1&gt;</span></span>
<span class="line"><span>- &lt;中文改动点2&gt;</span></span>
<span class="line"><span>- &lt;中文改动点3&gt;</span></span></code></pre></div><p><strong>如果你不确定 type 或 scope，也请给出建议并说明理由。</strong></p><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to &quot;使用示例&quot;">​</a></h2><p><strong>会话背景：</strong> 用户让 AI 在 UserService 中新增 resetPassword 方法，AI 生成了完整代码，并补充了对应的单元测试，还修改了 UserController 添加了对应的 API 端点。</p><p><strong>AI输出：</strong> feat(auth): 添加密码重置功能</p><ul><li>在 UserService 中实现 resetPassword 方法</li><li>新增 UserController.resetPassword API 端点</li><li>添加对应的单元测试（成功和失败场景）</li></ul><h2 id="迭代记录" tabindex="-1">迭代记录 <a class="header-anchor" href="#迭代记录" aria-label="Permalink to &quot;迭代记录&quot;">​</a></h2><ul><li>1.0.0 (2026-09-04): 初始版本</li></ul>`,18)])])}const u=t(o,[["render",l]]);export{m as __pageData,u as default};
